const raw = $input.first().json.stdout;
if (!raw) throw new Error('Evaluate batch returned no stdout; check HERMES_RESALE_REPO and Python availability.');
let report;
try { report = JSON.parse(raw); } catch (error) { throw new Error(`Evaluate batch returned invalid JSON: ${error.message}`); }
if (!report.research_only || !report.human_approval_required) throw new Error('Safety contract missing: expected research_only and human_approval_required.');
return [{ json: report }];
